#include "../protobuf_lite.h"
#include "test_harness.h"
#include <stddef.h>
#include <string.h>

TEST(test_pb_encode_varint_sentinel) {
    uint8_t backing[64];
    memset(backing, 0xFF, sizeof(backing));
    pb_encoder_t enc;
    pb_encoder_init(&enc, backing, sizeof(backing));
    pb_encode_varint(&enc, 1, 150);
    size_t used = pb_encoder_len(&enc);
    /* sentinel: byte after encoded data must be untouched */
    if (used > 0 && used < sizeof(backing)) {
        ASSERT_EQ(backing[used], 0xFF);
    }
}

